import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    k = int(input_data[1])

    if n % 2 == 1 and k > 0:
        print("-1")
        return

    if n == 1:
        if k == 0:
            print("1")
        else:
            print("-1")
        return

    pairs = n // 2
    base = k * 2

    result = []
    current_val = base

    for i in range(pairs):
        if i == 0:
            if k == 0:
                a = 1
                b = 2
            else:
                a = k
                b = k * 2
        else:
            a = current_val
            b = current_val + 1

        result.append(a)
        result.append(b)
        current_val += 2

    if n % 2 == 1:
        if n == 1:
            pass
        else:
